// Body shape expected: { source: 'vibe_prospecting'|'ucc', leads: [...] }
const body = $input.first().json.body ?? $input.first().json;
const source = body.source || 'unknown';
const leads = body.leads || [];
return leads.map(lead => ({ json: { ...lead, lead_source: source } }));

// Mirrors config/scoring-rules.json -- keep both in sync manually for now.
const lead = $input.item.json;
let score = 0;

const intentTopics = (lead.business_business_intent_topics || '');
const topicMatch = /"topic":"([^"]+)","score":(\d+)/.exec(intentTopics);
const topic = topicMatch ? topicMatch[1] : null;
const intentScore = topicMatch ? parseInt(topicMatch[2], 10) : 0;

if (topic === 'business finance: merchant cash advances') score += 25;
if (intentScore >= 70) score += 20;
else if (intentScore >= 60) score += 10;

const jobLevel = (lead.prospect_job_seniority_level || '').toLowerCase();
if (['owner', 'founder', 'president'].some(l => jobLevel.includes(l))) score += 20;

if (['500K-1M', '1M-5M'].includes(lead.business_yearly_revenue_range)) score += 15;

const naics = (lead.business_naics_description || '').toLowerCase();
if (/food services|construction|truck transportation/.test(naics)) score += 10;

if (lead.prospect_phone) score += 10;

const desc = (lead.business_business_description || '').toLowerCase();
if (/acquired by|subsidiary of/.test(desc)) score -= 50;

let priority = 'cold';
if (score >= 60) priority = 'hot';
else if (score >= 35) priority = 'warm';

return { json: { ...lead, score, priority } };

